css:
@font-face {
  font-family: "THSarabun";
  src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page { size: A4 landscape; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial, sans-serif;
  font-size: 9pt;
  color: #111;
}

.print-format { padding: 0 !important; margin: 0 !important; min-height: unset !important; max-width: unset !important; }
.print-format-preview { padding: 0 !important; }
.page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;
  page-break-after: always;
  background-size: 210mm 297mm;
  background-repeat: no-repeat;
  font-family: "THSarabun", "Sarabun", Arial, sans-serif;
  font-size: 11pt;
  color: #111;
}
.page:last-child { page-break-after: auto; }
.f { position: absolute; line-height: 1.08; white-space: normal; }

.field { position: absolute; line-height: 1.08; white-space: nowrap; }
.text-right { text-align: right; }
.amount { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.tr { text-align: right; }
.tc { text-align: center; }
.nowrap { white-space: nowrap; overflow: hidden; }
.small { font-size: 9.5pt; }
table { width: 100%; border-collapse: collapse; table-layout: fixed; }
td { padding: 0.8mm 1mm; vertical-align: top; line-height: 1.05; word-break: break-word; }

.page.hs-page {
  width: 297mm;
  height: 210mm;
  position: relative;
  overflow: hidden;
  background-image: url("/assets/connect_diagnostics_core/images/print_formats/hs6904013_1.webp?v=1779961457");
  background-size: 297mm 210mm;
  background-repeat: no-repeat;
  font-family: "THSarabun", "Sarabun", Arial, sans-serif;
  font-size: 8.2pt;
  color: #111;
}
.page.hs-page table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.page.hs-page td { padding: 0.35mm 0.3mm; vertical-align: top; line-height: 1.05; }
.col-no { width: 8mm; text-align: center; }
.col-desc { width: 60mm; }
.col-qty { width: 14mm; text-align: center; }
.col-rate { width: 16mm; text-align: right; white-space: nowrap; font-size: 7.5pt; }
.col-disc { width: 14mm; text-align: right; }
.col-amount { width: 20mm; text-align: right; white-space: nowrap; font-size: 7.5pt; }

/* CD Abbreviated Tax Invoice tuned overlay */
.si-customer-name { top: 52mm; width: 62mm; font-size: 8.8pt; }
.si-customer-address { top: 58mm; width: 62mm; font-size: 7.8pt; line-height: 1.05; }
.si-phone { top: 71mm; width: 45mm; font-size: 8pt; }
.si-tax-id { top: 70mm; width: 44mm; font-size: 8.6pt; }
.si-invoice-no { top: 47mm; width: 35mm; font-size: 8.8pt; }
.si-invoice-date { top: 57mm; width: 35mm; font-size: 8.8pt; }
.si-credit { top: 68mm; width: 24mm; font-size: 8pt; }
.si-due-date { top: 68mm; width: 27mm; font-size: 8.8pt; }
.si-reference { top: 77mm; width: 30mm; font-size: 8pt; }
.si-items { top: 88mm; width: 132mm; font-size: 8.5pt; }
.si-item-amount { display: inline-block; transform: translateX(-7mm); }

html:
{%- macro d(value) -%}{%- if value -%}{{ frappe.format_date(value, "dd/MM/yyyy") }}{%- endif -%}{%- endmacro -%}
{%- macro m(value) -%}{{ frappe.utils.fmt_money(value or 0, currency="") }}{%- endmacro -%}
{%- macro item_name(item) -%}{{ item.get("item_code") or "" }}{% if item.get("item_name") and item.get("item_name") != item.get("item_code") %} {{ item.get("item_name") }}{% endif %}{%- endmacro -%}
{%- macro render_copy(x) -%}
  <div class="f si-customer-name nowrap" style="left: {{ x + 17 }}mm;">{{ doc.get("customer_name") or doc.get("customer") or "" }}</div>
  <div class="f si-customer-address" style="left: {{ x + 17 }}mm;">{{ (doc.get("address_display") or "") | replace("<br>", " ") | replace("<br/>", " ") | striptags }}</div>
  <div class="f si-phone" style="left: {{ x + 17 }}mm;">{{ doc.get("contact_mobile") or doc.get("contact_phone") or "" }}</div>
  <div class="f si-tax-id" style="left: {{ x + 39 }}mm;">{{ doc.get("tax_id") or "" }}</div>
  <div class="f si-invoice-no" style="left: {{ x + 96 }}mm;">{{ doc.get("tax_invoice_number") or doc.get("name") }}</div>
  <div class="f si-invoice-date" style="left: {{ x + 84 }}mm;">{{ d(doc.get("tax_invoice_date") or doc.get("posting_date")) }}</div>
  <div class="f si-credit" style="left: {{ x + 84 }}mm;">{{ doc.get("payment_terms_template") or "" }}</div>
  <div class="f si-due-date" style="left: {{ x + 112 }}mm;">{{ d(doc.get("due_date")) }}</div>
  <div class="f si-reference" style="left: {{ x + 84 }}mm;">{{ doc.get("po_no") or "" }}</div>
  <div class="f si-items" style="left: {{ x + 13 }}mm;"><table>
    {%- for item in doc.get("items") or [] -%}
      {%- if loop.index <= 8 -%}
      <tr>
        <td class="col-no">{{ loop.index }}</td>
        <td class="col-desc">{{ item_name(item) }}</td>
        <td class="col-qty">{{ "%g"|format(item.get("qty") or 0) }}</td>
        <td class="col-rate">{{ frappe.utils.fmt_money(item.get("rate") or 0, currency="") }}</td>
        <td class="col-disc">{{ ("%g"|format(item.get("discount_percentage") or 0)) + "%" if item.get("discount_percentage") else "" }}</td>
        <td class="col-amount"><span class="si-item-amount">{{ frappe.utils.fmt_money(item.get("amount") or 0, currency="") }}</span></td>
      </tr>
      {%- endif -%}
    {%- endfor -%}
  </table></div>
  <div class="f tr" style="top: 145.5mm; left: {{ x + 122 }}mm; width: 16mm;">{{ m(doc.get("total")) }}</div>
  <div class="f tr" style="top: 157mm; left: {{ x + 122 }}mm; width: 16mm;">{{ m(doc.get("discount_amount")) if doc.get("discount_amount") else "-" }}</div>
  <div class="f tr" style="top: 166mm; left: {{ x + 122 }}mm; width: 16mm; font-weight: 700;">{{ m(doc.get("rounded_total") or doc.get("grand_total")) }}</div>
{%- endmacro -%}
<div class="page hs-page">
  {{ render_copy(0) }}
  {{ render_copy(148.5) }}
</div>
